import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React, { useMemo } from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import useDataset from "../../../client/useDataset";
import {
  applySolvedMapToPuzzleDisplays,
  useSolvedPuzzlesState,
} from "../../../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import TerminusBody from "./TerminusBody";
import { type TerminusResponseState, type TerminusState } from "./types";

const TerminusManager = ({
  initialState,
  initialTeamState,
  initialTerminusResponse,
  cutsceneContent,
}: {
  initialState: TerminusState;
  initialTeamState: TeamHuntState;
  initialTerminusResponse?: TerminusResponseState | null;
  cutsceneContent?: ResolvedCutsceneContent[];
}) => {
  const state = useDataset("terminus", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const { solvedMap } = useSolvedPuzzlesState();
  const mergedPuzzles = useMemo(() => {
    if (!IS_STATIC_SITE) return state.puzzles;
    return applySolvedMapToPuzzleDisplays(state.puzzles, solvedMap);
  }, [state.puzzles, solvedMap]);
  const mergedState = useMemo(() => {
    if (mergedPuzzles === state.puzzles) {
      return state;
    }
    const solved = mergedPuzzles
      .filter((puzzle) => Boolean(puzzle.puzzle.answer))
      .map((puzzle) => puzzle.puzzle.slug);
    return {
      ...state,
      puzzles: mergedPuzzles,
      progress: {
        ...state.progress,
        solved,
      },
    };
  }, [mergedPuzzles, state]);
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <TerminusBody
        state={mergedState}
        teamState={teamState}
        initialTerminusResponse={initialTerminusResponse}
        cutsceneContent={cutsceneContent}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("terminus-root");
if (elem) {
  const {
    initialTerminusState: state,
    initialTeamState: teamState,
    initialTerminusResponse,
    initialCutsceneContent: cutsceneContent,
  } = window as unknown as {
    initialTerminusState: TerminusState;
    initialTeamState: TeamHuntState;
    initialTerminusResponse?: TerminusResponseState | null;
    initialCutsceneContent?: ResolvedCutsceneContent[];
  };
  hydrateRoot(
    elem,
    <TerminusManager
      initialState={state}
      initialTeamState={teamState}
      initialTerminusResponse={initialTerminusResponse}
      cutsceneContent={cutsceneContent}
    />,
  );
} else {
  console.error(
    "Could not mount TerminusManager because #terminus-root was nowhere to be found",
  );
}
